def transform(grid):
    result = [row[:] for row in grid]

    # Find all 3x3 frames
    frame_centers = []
    for r in range(len(grid) - 2):
        for c in range(len(grid[0]) - 2):
            top = grid[r][c:c+3]
            middle = grid[r+1][c:c+3]
            bottom = grid[r+2][c:c+3]
            frame_val = top[0]
            if (top[0] == frame_val and top[1] == frame_val and top[2] == frame_val and
                middle[0] == frame_val and middle[2] == frame_val and
                bottom[0] == frame_val and bottom[1] == frame_val and bottom[2] == frame_val and
                frame_val != 0):
                center_r, center_c = r + 1, c + 1
                frame_centers.append((center_r, center_c))

    # Find horizontal lines that are NOT part of frames
    horizontal_lines = []
    for r in range(len(grid)):
        for c_start in range(len(grid[0])):
            line_len = 0
            for c in range(c_start, len(grid[0])):
                if grid[r][c] != 0:
                    line_len += 1
                else:
                    break

            if line_len < len(grid[0]) // 2:
                continue

            is_part_of_frame = False
            for frame_r, frame_c in frame_centers:
                if abs(r - frame_r) <= 1 and c_start <= frame_c + 1 and c_start + line_len >= frame_c - 1:
                    is_part_of_frame = True
                    break

            if not is_part_of_frame:
                horizontal_lines.append((r, c_start, line_len, grid[r][c_start]))
                break

    if frame_centers and horizontal_lines:
        line_r, _, _, line_val = horizontal_lines[0]
        frame_ccx = frame_centers[0][1]

        # Cross center at (line_r, frame_ccx)
        # Vertical: 3 rows above, 3 rows below (total 7 rows), 1 column wide
        v_cross_r_start, v_cross_r_end = line_r - 3, line_r + 3
        v_cross_c = frame_ccx

        # Horizontal: 3 rows, 3 columns (1 above, 1 below, center)
        h_cross_r_start, h_cross_r_end = line_r - 1, line_r + 1
        h_cross_c_start, h_cross_c_end = frame_ccx - 1, frame_ccx + 1

        # Fill vertical cross
        for r in range(max(0, v_cross_r_start), min(len(result), v_cross_r_end + 1)):
            for c in range(max(0, v_cross_c), min(len(result[0]), v_cross_c + 1)):
                if r < len(result) and c < len(result[0]):
                    if result[r][c] == 0:
                        result[r][c] = 1

        # Fill horizontal cross (including the vertical part to avoid double-filling)
        for r in range(max(0, h_cross_r_start), min(len(result), h_cross_r_end + 1)):
            for c in range(max(0, h_cross_c_start), min(len(result[0]), h_cross_c_end + 1)):
                if r < len(result) and c < len(result[0]):
                    if result[r][c] == 0:
                        result[r][c] = 1

    return result

